INSERT INTO content_items (id, type, slug, name, eyebrow, summary, body, start_year, end_year, brand_id, category_id, accent, status, quality_status, featured, metadata, content_version, verified_at, published_at, created_at, updated_at) VALUES ('phone-anycall-sch-v500', 'phone', 'anycall-sch-v500', 'Anycall SCH-V500', '화면을 돌린 가로본능', '세로 화면이라는 상식을 깨고 LCD를 가로로 회전시킨 메가픽셀 VOD 폴더폰', 'SCH-V500은 폴더를 연 뒤 화면을 90도로 돌려 사진과 VOD를 가로로 볼 수 있게 만든 애니콜입니다. 2.2인치 QVGA 화면, 메가픽셀 카메라, MP3와 3D 게임을 한 기기에 담았습니다.', 2004, NULL, 'brand-90e01d646458', 'category-phone', '#94a3b8', 'published', 'verified', 1, '{"highlights":["90도 회전 LCD","메가픽셀 사진·동영상","MP3·3D 게임"],"specs":{"제조사":"삼성전자","출시":"2004년 8월","형태":"스위블 폴더","가격":"70만원대"},"story":{"significance":"영상은 가로로 본다는 사용 습관을 휴대전화 폼팩터에 직접 반영해, 기능과 외형이 함께 경험을 설계할 수 있음을 보여준 제품입니다.","legacy":"회전·폴더·듀얼 스크린으로 이어진 실험적 폼팩터의 선례가 되었고, 모바일 영상 감상이 제품 형태를 바꾸는 흐름을 일찍 보여줬습니다."}}', 3, 1786579200000, 1786579200000, 1786579200000, 1786579200000) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug, name=excluded.name, eyebrow=excluded.eyebrow, summary=excluded.summary, body=excluded.body, start_year=excluded.start_year, brand_id=excluded.brand_id, category_id='category-phone', accent=excluded.accent, status='published', quality_status='verified', featured=excluded.featured, metadata=excluded.metadata, content_version=3, verified_at=excluded.verified_at, updated_at=excluded.updated_at;
