INSERT INTO content_items (id, type, slug, name, eyebrow, summary, body, start_year, end_year, brand_id, category_id, accent, status, quality_status, featured, metadata, content_version, verified_at, published_at, created_at, updated_at) VALUES ('phone-curitel-ph-s3500', 'phone', 'curitel-ph-s3500', 'Curitel PH-S3500', '동그란 3D 게임폰', '원형 폴더와 전용 그래픽 칩으로 휴대전화를 손안의 게임기로 해석한 큐리텔', 'PH-S3500은 원형 상판과 양손 조작용 방향·슈팅 버튼, 별도 3D 그래픽 가속칩을 결합한 피처폰입니다. MP3와 카메라까지 더해 모바일 엔터테인먼트 기기를 지향했습니다.', 2004, NULL, 'brand-b0fcd51c4f2e', 'category-phone', '#b7a48d', 'published', 'verified', 0, '{"highlights":["3D 그래픽 가속칩","양손 게임 조작 버튼","듀얼 스피커와 MP3"],"specs":{"제조사":"팬택&큐리텔","출시":"2004년 10월","형태":"원형 폴더","화면":"2.1인치 와이드 LCD"},"story":{"significance":"통화 중심 설계를 벗어나 특정 취미인 게임에 맞춰 외형과 버튼 배치를 바꾼 국내 피처폰 시대의 대담한 실험입니다.","legacy":"전용 게임폰은 주류가 되지 못했지만, 고성능 모바일 GPU와 게임 전용 액세서리·게이밍폰으로 이어지는 발상을 앞서 보여줬습니다."}}', 3, 1786579200000, 1786579200000, 1786579200000, 1786579200000) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug, name=excluded.name, eyebrow=excluded.eyebrow, summary=excluded.summary, body=excluded.body, start_year=excluded.start_year, brand_id=excluded.brand_id, category_id='category-phone', accent=excluded.accent, status='published', quality_status='verified', featured=excluded.featured, metadata=excluded.metadata, content_version=3, verified_at=excluded.verified_at, updated_at=excluded.updated_at;
