INSERT OR IGNORE INTO content_revisions (id, content_id, version, snapshot, note, created_at) VALUES ('revision-v032-914c2fdb64bb', 'phone-curitel-ph-s3500', 3, '{"name":"Curitel PH-S3500","summary":"원형 폴더와 전용 그래픽 칩으로 휴대전화를 손안의 게임기로 해석한 큐리텔","description":"PH-S3500은 원형 상판과 양손 조작용 방향·슈팅 버튼, 별도 3D 그래픽 가속칩을 결합한 피처폰입니다. MP3와 카메라까지 더해 모바일 엔터테인먼트 기기를 지향했습니다.","specs":{"제조사":"팬택&큐리텔","출시":"2004년 10월","형태":"원형 폴더","화면":"2.1인치 와이드 LCD"},"story":{"significance":"통화 중심 설계를 벗어나 특정 취미인 게임에 맞춰 외형과 버튼 배치를 바꾼 국내 피처폰 시대의 대담한 실험입니다.","legacy":"전용 게임폰은 주류가 되지 못했지만, 고성능 모바일 GPU와 게임 전용 액세서리·게이밍폰으로 이어지는 발상을 앞서 보여줬습니다."},"source":{"label":"전자신문 출시 보도","url":"https://www.etnews.com/200409300156"},"image":{"src":"/images/archive/devices/curitel-ph-s3500.jpg","alt":"원형 외부 화면을 갖춘 은색 Curitel PH-S3500 제품 정면","credit":"Bunjang 판매자 제공 이미지","sourceUrl":"https://globalbunjang.com/product/333330999","license":"원저작자 권리 보유 · 출처 표기"}}', 'v0.3.2 Korean feature phone archive', 1786579200000);
